//! Cloud instance presets (step 8P, RULES 102 b, 110, 113): `instance: aws/m5.large` on a node fills
//! its `cpu.cores`, its network card (`bandwidth`) and the limit of its `memory`. One embedded
//! table, `data/instances.csv`, generated by `scripts/gen-instances.mjs` from public catalogues of
//! AWS, Azure and GCP; a value the user writes always wins.
//!
//! **Every number is an estimate**, rounded, as of the date in the csv header. Three traps, which
//! the docs repeat:
//! - a vCPU is a hardware thread, not a core, and the engine counts it as a full core, so a preset
//!   is an **upper bound** on compute capacity; per-core speed differs between families (a preset
//!   gives capacity, not speed: service times stay yours);
//! - the network figure is a peak ("up to") rate, and a `0` means the source gives none (the card
//!   is then not limited, which is what an absent `bandwidth` means);
//! - burstable types (`t3`, `e2-medium`, `B`-series) run above their baseline only on CPU credits,
//!   which are not modelled: they are listed at their full vCPU count, an upper bound.

use std::sync::OnceLock;

/// One instance type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Instance {
    /// `provider/type`, lower case: what `instance:` takes.
    pub name: &'static str,
    /// vCPUs (hardware threads).
    pub vcpu: u32,
    /// Memory in MiB.
    pub memory_mib: u32,
    /// Peak network rate in megabits per second; 0 = the source gives none (not limited).
    pub net_mbps: u32,
    /// On-demand Linux price of one hour in micro-USD (1,000,000 = 1 dollar), in the provider's one
    /// default region (AWS us-east-1, Azure East US, GCP us-central1); 0 = no price. An integer on
    /// purpose: money is added up here and a float would drift. An estimate, never a quote.
    pub price_micro_usd_hr: u32,
}

impl Instance {
    /// The peak network rate in bytes per second, `None` when the source gives none.
    #[must_use]
    pub const fn net_bytes_per_s(&self) -> Option<u64> {
        if self.net_mbps == 0 {
            None
        } else {
            Some(self.net_mbps as u64 * 1_000_000 / 8)
        }
    }

    /// The memory in bytes.
    #[must_use]
    pub const fn memory_bytes(&self) -> u64 {
        self.memory_mib as u64 * (1 << 20)
    }
}

/// The csv as generated (`name,vcpu,memory_mib,net_mbps,usd_micro_hr`, sorted by name, `#` lines are
/// comments).
const CSV: &str = include_str!("../data/instances.csv");

/// The table, parsed once.
fn table() -> &'static [Instance] {
    static TABLE: OnceLock<Vec<Instance>> = OnceLock::new();
    TABLE.get_or_init(|| {
        CSV.lines()
            .filter(|l| !l.is_empty() && !l.starts_with('#'))
            .map(|l| {
                let mut f = l.split(',');
                let mut next = || f.next().expect("a csv field");
                let name = next();
                let (vcpu, memory_mib, net_mbps, price) = (next(), next(), next(), next());
                Instance {
                    name,
                    vcpu: vcpu.parse().expect("vcpu is a number"),
                    memory_mib: memory_mib.parse().expect("memory is a number"),
                    net_mbps: net_mbps.parse().expect("network is a number"),
                    price_micro_usd_hr: price.parse().expect("price is a number"),
                }
            })
            .collect()
    })
}

/// Every instance type, sorted by name.
#[must_use]
pub fn all() -> &'static [Instance] {
    table()
}

/// The instance named `name` (case-insensitive), if the table has it.
#[must_use]
pub fn lookup(name: &str) -> Option<&'static Instance> {
    let key = name.trim().to_ascii_lowercase();
    let t = table();
    t.binary_search_by(|x| x.name.cmp(key.as_str()))
        .ok()
        .map(|k| &t[k])
}

/// The type part of `provider/type`, lower case.
fn type_part(name: &str) -> Option<String> {
    name.trim()
        .to_ascii_lowercase()
        .split_once('/')
        .map(|(_, t)| t.to_string())
}

/// Whether `name` is a managed database class (`aws/db.m5.large`, from AWS RDS). The table holds
/// these with the VM types; a class's type part starts with `db.`, which no VM type does.
#[must_use]
pub fn is_db_class(name: &str) -> bool {
    type_part(name).is_some_and(|t| t.starts_with("db."))
}

/// Whether `name` is a managed cache class (`aws/cache.m5.large`, from AWS `ElastiCache`).
#[must_use]
pub fn is_cache_class(name: &str) -> bool {
    type_part(name).is_some_and(|t| t.starts_with("cache."))
}

/// Whether `name` is a managed class of either kind and not a VM type.
#[must_use]
pub fn is_managed_class(name: &str) -> bool {
    is_db_class(name) || is_cache_class(name)
}

/// A hint for an unknown name: how many types that provider has and a few of its names that start
/// like the one written, or the providers when it names none.
#[must_use]
pub fn hint(name: &str) -> String {
    let key = name.trim().to_ascii_lowercase();
    let (provider, rest) = key.split_once('/').unwrap_or((key.as_str(), ""));
    let prefix = format!("{provider}/");
    let same: Vec<&str> = table()
        .iter()
        .map(|x| x.name)
        .filter(|n| n.starts_with(&prefix))
        .collect();
    if same.is_empty() {
        return "write provider/type, with the provider aws, azure or gcp, like aws/m5.large"
            .into();
    }
    let near: Vec<&str> = same
        .iter()
        .copied()
        .filter(|n| n[prefix.len()..].starts_with(rest.get(..rest.len().min(2)).unwrap_or("")))
        .take(5)
        .collect();
    let shown = if near.is_empty() {
        &same[..same.len().min(5)]
    } else {
        &near[..]
    };
    format!(
        "{provider} has {} types, for example {}",
        same.len(),
        shown.join(", ")
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_sorted_unique_and_every_row_has_a_cpu_and_memory() {
        let t = all();
        assert!(t.len() > 1000, "{} types", t.len());
        assert!(t.windows(2).all(|w| w[0].name < w[1].name));
        for x in t {
            assert!(x.vcpu >= 1 && x.memory_mib >= 1, "{x:?}");
            assert!(x.name.contains('/') && x.name == x.name.to_ascii_lowercase());
            assert_eq!(lookup(x.name), Some(x));
        }
    }

    #[test]
    fn all_three_providers_are_there_in_numbers() {
        for (p, at_least) in [("aws/", 500), ("azure/", 500), ("gcp/", 200)] {
            let n = all().iter().filter(|x| x.name.starts_with(p)).count();
            assert!(n >= at_least, "{p}: {n}");
        }
    }

    #[test]
    fn lookup_ignores_case_and_space_and_refuses_the_unknown() {
        let m5 = lookup("  AWS/M5.Large ").unwrap();
        assert_eq!((m5.vcpu, m5.memory_mib), (2, 8192));
        assert_eq!(m5.net_bytes_per_s(), Some(1_250_000_000));
        assert!(lookup("aws/m5.huge").is_none());
        assert!(hint("aws/m5.huge").starts_with("aws has "));
        assert!(hint("mars/x1").contains("provider/type"));
    }

    #[test]
    fn well_known_types_have_the_published_shape() {
        // AWS, Azure and GCP each list these sizes; the figures are from the providers' pages
        for (name, vcpu, gib) in [
            ("aws/c6i.xlarge", 4, 8),
            ("aws/r6i.large", 2, 16),
            ("azure/standard_d4s_v5", 4, 16),
            ("gcp/n2-standard-8", 8, 32),
            ("gcp/e2-standard-2", 2, 8),
        ] {
            let x = lookup(name).unwrap_or_else(|| panic!("{name} is missing"));
            assert_eq!((x.vcpu, x.memory_mib), (vcpu, gib * 1024), "{name}");
        }
    }
}
